             .iter()
             .filter_map(|id| self.widgets.get(id).cloned())
             .collect();
         if current == target {
             return;
         }
         if let Ok(bx) = parent.clone().downcast::<GtkBox>() {
             for w in current {
                 bx.remove(&w);
             }
             for w in &target {
                 bx.append(w);
             }
         }
