/// Re-append the tree-ordered child widgets to a box (order/content diff).
    fn reconcile_box_children(&mut self, parent: &gtk::Widget, children: &[u32]) {
        let current = child_widgets(parent);
        let target: Vec<gtk::Widget> = children
            .iter()
            .filter_map(|id| self.widgets.get(id).cloned())
            .collect();
        if current == target {
            return;
        }
        if let Ok(bx) = parent.clone().downcast::<GtkBox>() {
            for w in current {
                bx.remove(&w);
            }
            for w in &target {
                bx.append(w);
            }
        }
    }

    /// Reconcile a navigation slot's pages against the app's current
    /// destination. The slot always carries exactly one child — the current
    /// destination subtree — plus a `ROUTE` string. Pages are keyed by that
    /// `ROUTE` tag, so the renderer can:
    ///
    /// - **push** a new page when the route has no page yet,
    /// - **pop** back to an existing page when the route resolves to one
    ///   already on the native stack (back/gesture/Escape → `NAVIGATE` →
    ///   app `pop()` → re-emit),
    /// - **refresh in place** (no transition) when the visible page's route is
    ///   already current (a signal-driven update of the same destination).
    ///
    /// The back-stack stays app-owned; the `AdwNavigationView` is only the
    /// renderer's rendered-output cache of it (a `ROUTE`-keyed page per
    /// destination it has shown). Programmatic pops here are guarded so they
    /// never re-emit as a back request.
    fn sync_navigation_children(&mut self, slot_id: u32, children: &[u32], node: &HostNode) {
        let Some(nav) = self.nav_views.get(&slot_id).cloned() else {
            return;
        };
        let Some(target) = children
            .first()
            .and_then(|id| self.widgets.get(id).cloned())
        else {
            return;
        };
        // Pages are keyed by the ROUTE tag; without a ROUTE the slot is not a
        // navigation slot (the renderer would not have promoted it).
        let route = node.string_property(property_id::ROUTE).unwrap_or_default();

        self.attach_nav_back(slot_id, &nav);

        if let Some(page) = nav.find_page(&route) {
            // Refresh the (possibly freshly rebuilt) destination widget, then
            // return to it if it isn't the visible page.
            page.set_child(Some(&target));
            if nav.visible_page().as_ref() != Some(page) {
                if let Some(flag) = self.nav_reconciling.get(&slot_id) {
                    flag.set(true);
                }
                nav.pop_to_page(&page);
                if let Some(flag) = self.nav_reconciling.get(&slot_id) {
                    flag.set(false);
                }
            }
        } else {
            let page = nav_page(&route, &route, &target);
            nav.push(&page);
        }
    }

    /// Wire the native back affordance of a navigation slot once: when a page
    /// is popped (the header-bar back button, or a swipe/gesture), emit
    /// `Event::Navigate { url: None }` so the app pops its own back-stack and
    /// re-emits the previous destination. Suppressed while the renderer pops
    /// pages itself during reconcile.
    fn attach_nav_back(&mut self, slot_id: u32, nav: &NavigationView) {
        if self.nav_back_attached.contains(&slot_id) {
            return;
        }
        let flag = Rc::new(Cell::new(false));
        self.nav_reconciling.insert(slot_id, flag.clone());
        if let Some(sink) = self.event_sink.clone() {
            nav.connect_popped(move |_nav, _page| {
                if !flag.get() {
                    sink.borrow_mut()(Event::Navigate { url: None });
                }
            });
        }
        self.nav_back_attached.insert(slot_id);
    }
}

