/// Build an `AdwNavigationPage` for a navigation slot: the destination widget
/// wrapped in a `AdwToolbarView` with an `AdwHeaderBar`, so the page gets the
/// native top bar and the back button appears once the page is not the root.
/// The page's tag is the `ROUTE` path — pages are reconciled by it, and the
/// native back button's pop (via `popped`) surfaces as a `NAVIGATE` request.
fn nav_page(route: &str, title: &str, child: &gtk::Widget) -> adw::NavigationPage {
    let toolbar = adw::ToolbarView::new();
    let header = adw::HeaderBar::new();
    header.set_show_back_button(true);
    // No window controls in the page header — the app's own content provides
    // them; only the navigation back button is native chrome.
    header.set_show_start_title_buttons(false);
    header.set_show_end_title_buttons(false);
    toolbar.add_top_bar(&header);
    toolbar.set_content(Some(child));
    adw::NavigationPage::builder()
        .title(title)
        .tag(route)
        .child(&toolbar)
        .build()
}

