        use component_type::*;
        let node = HostNode {
            id: 1,
            component_type: VSTACK,
            text: None,
            children: vec![],
            properties: HashMap::new(),
            strings: HashMap::from([(property_id::ROUTE, "/".into())]),
        };
        let w = build_widget(&node);
        assert!(
            w.is::<NavigationView>(),
            "a ROUTE stack must render as AdwNavigationView"
        );
        // Without ROUTE the same component builds a plain box.
        let plain = HostNode {
            id: 2,
            component_type: VSTACK,
            text: None,
            children: vec![],
            properties: HashMap::new(),
            strings: HashMap::new(),
        };
        let w = build_widget(&plain);
        assert!(
            !w.is::<NavigationView>(),
            "a plain stack must not become a navigation view"
        );
    }

    #[test]
    fn nav_page_is_tagged_by_route() {
