            let node = HostNode {
                id: 2,
                component_type: TEXT,
                text: Some("home".into()),
                children: vec![],
                properties: HashMap::new(),
                strings: HashMap::new(),
            };
            build_widget(&node)
        };
        let page = nav_page("/", "/", &child);
        assert_eq!(page.tag().as_deref(), Some("/"), "page tag = ROUTE");
        assert_eq!(page.title(), "/", "page title = ROUTE");
    }

