     pub const VIEWPORT_HEIGHT: u16 = 0x0002;
     /// The initial route/deep-link path (STRING: `B` is a string-section/event-arena
     /// offset — the `TEXT_CHANGED`/`NAVIGATE` dual convention).
     pub const ROUTE: u16 = 0x0003;
