     pub const POINTER_MOVE: u32 = 1 << 1;
     /// `POINTER_UP` events (bit 2).
     pub const POINTER_UP: u32 = 1 << 2;
     /// `KEY_DOWN` events (bit 3).
     pub const KEY_DOWN: u32 = 1 << 3;
     /// `KEY_UP` events (bit 4).
     pub const KEY_UP: u32 = 1 << 4;
