```java
// com.pathland.view.EnvironmentKey<T>
public final class EnvironmentKey<T> { ... }

// com.pathland.view.EnvironmentValues — immutable scope chain
final class EnvironmentValues {
    static final EnvironmentValues EMPTY;
    final EnvironmentKey<?> key; final Object value; final EnvironmentValues parent;
    EnvironmentValues with(...); <T> T get(EnvironmentKey<T>);
}

// Environment
public final class Environment {
    static final ThreadLocal<EnvironmentValues> VALUES = ThreadLocal.withInitial(() -> EnvironmentValues.EMPTY);
    public static void push(key, value) { ... }   // used by the scoping modifier
    public static void restore(previous) { ... }
