+package com.pathland.view.router;
+
+import com.pathland.view.View;
+
+/**
+ * A bundled navigation app: the mountable root view plus the {@link Router} that
+ * drives it (spec DSL.md §4.5). The host mounts {@link #root()} and uses
+ * {@link #routeTo(String)} to re-route when the platform environment moves (a deep
+ * link, browser back/forward {@code popstate}, a native back) — the router itself is
+ * otherwise hidden from the host (it is provided to the tree as a scoped environment
+ * value, {@link Navigation#ROUTER}).
+ *
+ * <p>Built by a root view's {@code app(initialPath)} factory, e.g.:
+ * <pre>{@code
+ * NavigationApp app = SplitNavDemo.app(env.route());
+ * emitter.mount(app.root(), new Environment(state));
+ * app.routeTo(env.route());   // idempotent re-route
+ * }</pre>
+ *
+ * @param root   the view tree to mount
+ * @param router the router driving the app (host re-routes via {@link #routeTo})
+ */
+public record NavigationApp(View root, Router router) {
+
+    /** Bundle a mountable root view with its router. */
+    public static NavigationApp of(View root, Router router) {
+        return new NavigationApp(root, router);
+    }
+
+    /** Re-route to {@code path} if the platform environment moved there (idempotent). */
+    public void routeTo(String path) {
+        if (!path.equals(router.path())) {
+            router.navigate(path);
+        }
+    }
+}
