    @Test
    void environmentScopingIsHierarchicalAndScoped() {
        // A scoped `.environment(key, value)` is active only for its subtree; an inner
        // binding overrides an outer one, and the value is restored afterward.
        com.pathland.view.EnvironmentKey<String> key = com.pathland.view.EnvironmentKey.of("k");
        java.util.List<String> seen = new java.util.ArrayList<>();

        View probe = new View() {
            @Override
            public com.pathland.view.emit.PathlandNode render(Environment env) {
                seen.add(com.pathland.view.Environment.value(key));
                return new com.pathland.view.emit.PathlandNode(com.pathland.view.Components.TEXT);
            }
        };

        View outer = probe.environment(key, "outer").environment(key, "inner");
        // Render twice: the scope must not leak between renders (restore).
        new Emitter(sink()).mount(outer, Environment.DEFAULT);
        new Emitter(sink()).mount(probe.environment(key, "outer"), Environment.DEFAULT);

        assertEquals("inner", seen.get(0), "nearest binding wins");
        assertEquals("outer", seen.get(1), "outer binding applies when no inner override");
        assertEquals(null, com.pathland.view.Environment.value(key), "no leak after render (restored)");
    }

    @Test
    void navigationAppBundlesRootAndRouterForTheHost() {
        // The host DX: SplitNavDemo.app(...) bundles a seeded router + a mountable root;
        // the router is provided to the tree as the Navigation.ROUTER environment value.
        // (This test uses the demo's app via Navigation.navigator + .environment directly
        // to stay in the view library; the demo module covers SplitNavDemo.app itself.)
        Router router = Navigation.navigator("/kitchen")
                .route("/", Text.of("Home"))
                .route("/kitchen", Text.of("Kitchen"))
                .build();
        NavigationApp app = NavigationApp.of(
                Text.of("Home").environment(Navigation.ROUTER, router), router);

        assertEquals("/kitchen", app.router().path(), "the bundled router is seeded");
        app.routeTo("/"); // host re-route
        assertEquals("/", app.router().path(), "routeTo re-routes when the path differs");
        app.routeTo("/"); // idempotent
        assertEquals("/", app.router().path(), "routeTo is idempotent on the same path");
    }
}

