package com.pathland.view;

import com.pathland.view.signal.WritableSignal;

/**
 * Platform-level environment values and helpers (spec DSL.md §4.5). Unlike
 * {@code Navigation.ROUTER} (the router *instance*, only present when navigation is
 * declared), the active platform path is provided by the host for **every** app —
 * with or without navigation — so any app can observe the current path (a web URL, a
 * native deep link / open event, the initial route) like SwiftUI's {@code onOpenURL},
 * generalized across platforms.
 *
 * <pre>{@code
 * // host (always):
 * WritableSignal<String> activePath = Signals.signal(env.route());
 * emitter.mount(root.environment(Platform.ACTIVE_PATH, activePath), env);
 *
 * // app — with or without navigation:
 * view.onPathChange(path -> handlePlatformPath(path));
 * }</pre>
 */
public final class Platform {

    /** The environment key for the app's active platform path (a writable signal). */
    public static final EnvironmentKey<WritableSignal<String>> ACTIVE_PATH = EnvironmentKey.of("platform.activePath");

    private Platform() {}
}

package com.pathland.view;

import java.util.function.Consumer;

/**
 * Registers a listener for the active platform path (spec DSL.md §4.5) — the
 * SwiftUI {@code onOpenURL} idea generalized across platforms. Applied via
 * {@code View#onPathChange(Consumer)}. The listener fires whenever the
 * {@link Platform#ACTIVE_PATH} signal changes (including its initial value);
 * a {@code Router}, when present, binds to the same signal.
 */
public final class PathChangeMod implements ViewModifier {

    private final Consumer<String> listener;

    PathChangeMod(Consumer<String> listener) {
        this.listener = listener;
    }

    @Override
    public View body(View content) {
        return new PathChangeView(content, listener);
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;

import java.util.function.Consumer;

/**
 * A view wrapped by {@code onPathChange}: records the listener on the built node and
 * captures the active-path signal it should watch (the {@link Platform#ACTIVE_PATH}
 * environment value). The emitter registers a node-level effect that fires the
 * listeners when the signal changes, and destroys it when the subtree is replaced.
 */
final class PathChangeView implements View {

    private final View content;
    private final Consumer<String> listener;

    PathChangeView(View content, Consumer<String> listener) {
        this.content = content;
        this.listener = listener;
    }

    @Override
    public PathlandNode render(Environment env) {
        PathlandNode node = content.render(env);
        node.pathChangeListeners.add(listener);
        node.activePath = Platform.ACTIVE_PATH != null
                ? Environment.value(Platform.ACTIVE_PATH)
                : null;
        return node;
    }
}

