@Path("/")
public class IndexResource {

    @Inject
    PathlandApp app;

    /** The root page (the route is {@code /}). */
    @GET
    @Produces(MediaType.TEXT_HTML)
    public Response index(@CookieParam("session") String sessionId) {
        return render("/", sessionId);
