package com.pathland.server;

import com.pathland.view.ThemeData;
import com.pathland.view.View;

/**
 * The application's root-view factory — the single app-specific piece the server
 * runtime needs. A host (Spring Boot / Quarkus starter) provides one as a bean; the
 * runtime mounts a fresh root per session (views hold per-session {@code State}).
 *
 * <pre>{@code
 * @Bean PathlandApp pathlandApp() { return () -> new MyHomeView(); }
 * }</pre>
 */
@FunctionalInterface
public interface PathlandApp {

    /** A fresh root view for a new session. */
    View newRoot();

    /** The optional global theme (design-token overrides); {@code null} for none. */
    default ThemeData theme() {
        return null;
    }
}

package com.pathland.server;

/**
 * The transport seam (spec DSL.md §4.5): the server runtime sends delta frames through
 * this, so the session logic is framework-agnostic. Each starter adapts its WebSocket
 * type (Spring {@code WebSocketSession}, Quarkus {@code WebSocketConnection}) to it.
 */
public interface PathlandConnection {

    /** Send a self-contained delta/snapshot frame to this connection's client. */
    void send(byte[] bytes);

    /** Whether the connection can currently accept a send. */
    boolean isOpen();
}

package com.pathland.server;

import com.pathland.render.html.HtmlRenderer;
import com.pathland.view.Environment;
import com.pathland.view.Platform;
import com.pathland.view.emit.DateInput;
import com.pathland.view.emit.Emitter;
import com.pathland.view.emit.Frame;
import com.pathland.view.emit.FrameOpcodeSink;
import com.pathland.view.emit.RenderResult;
import com.pathland.view.signal.Signals;
import com.pathland.view.signal.WritableSignal;
import com.pathland.view.state.PersistentState;
import com.pathland.view.state.StateStore;
import com.pathland.view.transport.EnvironmentData;
import com.pathland.view.transport.Event;
import com.pathland.view.transport.FrameCodec;

import java.util.Map;
import java.util.function.Consumer;

/**
 * One Pathland application instance per session (1:1 with a client). Owns the session's
 * {@link PersistentState}, the retained tree, the fine-grained emitter, and the single
 * connection it sends deltas to — all transport-agnostic ({@link PathlandConnection}).
 *
 * <p>The platform environment (spec/OPCODE.md §Environment fields) seeds the app: the
 * initial route comes from its {@code ROUTE} field (a request URL on SSR; the DOM
 * client's first message over the WebSocket), delivered to the tree as the
 * {@code Platform.ACTIVE_PATH} signal. Later environment messages **enrich** the session
 * (viewport resizes, future fields) via {@link #applyEnvironment}.
 *
 * <p>State wiring is automatic: {@code State} fields in the app's views connect to the
 * store at mount. The connection is wired only <em>after</em> mount, so the mount frame
 * (already SSR'd) is never re-sent.
 */
public final class PathlandSession {

    private final PersistentState state;
    private final WritableSignal<String> activePath;

    private final FrameOpcodeSink sink;
    private final Emitter emitter;
    private final Map<Integer, Runnable> tapActions;
    private final Map<Integer, Runnable> navigateActions;
    private final Map<Integer, Consumer<String>> textInputs;
    private final Map<Integer, Consumer<Float>> valueInputs;
    private final Map<Integer, DateInput> dateInputs;
    private final Consumer<Event> navigateHandler;
    private final int rootId;

    private float viewportWidth = -1f;
    private float viewportHeight = -1f;

    private volatile PathlandConnection connection;

    public PathlandSession(String sessionId, StateStore store, PathlandApp app, EnvironmentData env) {
        this.state = new PersistentState(store, sessionId);
        // The active platform path is a host-provided signal (Platform.ACTIVE_PATH); the
        // app reads it, and a bound Router re-routes guard-aware on external changes.
        this.activePath = Signals.signal(env.route());

        this.sink = new FrameOpcodeSink() {
            @Override
            public void endFrame() {
                super.endFrame();
                Frame frame = frame();
                if (!frame.opcodes().isEmpty()) {
                    // The mount frame (emitted in the constructor, before the session
                    // attaches) is NOT sent — the client already has the whole UI from
                    // the HTML. Only deltas + resync snapshots go out.
                    send(frame);
                }
            }
        };
        this.emitter = new Emitter(sink, app.theme());

        // Mount wires State fields, then renders and emits the structural frame. The
        // active path is injected as a scoped environment value; any root works (with or
        // without navigation).
        RenderResult result = emitter.mount(
                app.newRoot().environment(Platform.ACTIVE_PATH, activePath),
                new Environment(state));
        this.tapActions = result.tapActions();
        this.navigateActions = result.navigateActions();
        this.textInputs = result.textInputs();
        this.valueInputs = result.valueInputs();
        this.dateInputs = result.dateInputs();
        this.navigateHandler = result.navigateHandler();
        this.rootId = result.rootId();
        applyEnvironment(env); // records viewport; the router already seeded from env.route()
    }

    /** Apply (or enrich) the platform environment after mount (viewport resizes, …). */
    public void applyEnvironment(EnvironmentData env) {
        activePath.set(env.route()); // re-route if the platform moved (guards run in the bound router)
        if (env.viewportWidth() > 0) {
            viewportWidth = env.viewportWidth();
        }
        if (env.viewportHeight() > 0) {
            viewportHeight = env.viewportHeight();
        }
    }

    /** Wire the live connection AFTER mount (the initial frame was already SSR'd). */
    public void connect(PathlandConnection connection) {
        this.connection = connection;
    }

    /** Re-send the current tree as a full snapshot (META::RESYNC). */
    public void resync() {
        emitter.renderFull();
    }

    private void send(Frame frame) {
        PathlandConnection conn = connection;
        if (conn == null || !conn.isOpen()) {
            connection = null;
            return;
        }
        byte[] bytes = FrameCodec.encodeFrame(frame);
        try {
            conn.send(bytes);
        } catch (Exception e) {
            connection = null;
        }
    }

    /** Route an inbound event batch (raw host → guest opcodes) into the app's bindings. */
    public void dispatch(byte[] message) {
        try {
            for (Event event : FrameCodec.decodeEvents(message)) {
                if (event.isPointerUp()) {
                    // A declared navigation intent (`.navigate/.push/.replace`) wins over a
                    // plain tap action — route it first (spec DSL.md §4.5).
                    Runnable nav = navigateActions.get(event.target());
                    if (nav != null) {
                        nav.run();
                    } else {
                        Runnable action = tapActions.get(event.target());
                        if (action != null) {
                            action.run();
                        }
                    }
                } else if (event.isTextChanged()) {
                    Consumer<String> sink = textInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.text());
                    }
                } else if (event.isValueChanged()) {
                    Consumer<Float> sink = valueInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.value());
                    }
                } else if (event.isDateChanged()) {
                    DateInput sink = dateInputs.get(event.target());
                    if (sink != null) {
                        sink.accept(event.days(), event.millisOfDay());
                    }
                } else if (event.isNavigate()) {
                    if (event.url() != null) {
                        // A URL (deep link / popstate): update the active path — a bound
                        // Router re-routes guard-aware, and any onPathChange listener fires.
                        activePath.set(event.url());
                    } else {
                        // "Back one step" has no path — only meaningful with a Router.
                        Consumer<Event> sink = navigateHandler;
                        if (sink != null) {
                            sink.accept(event);
                        }
                    }
                }
            }
        } catch (RuntimeException e) {
            log("dropping event batch: " + e.getMessage());
        }
    }

    /** Render the SSR HTML for this session's current tree (request thread). */
    public String renderHtml() {
        HtmlRenderer renderer = HtmlRenderer.tryInstance();
        if (renderer == null) {
            return "<!DOCTYPE html><html><body><h1>Pathland renderer unavailable</h1>"
                    + "<p>Build the Rust crate so libpathland_render_html is embedded in the "
                    + "pathland-render-html jar.</p></body></html>";
        }
        return renderer.render(sink.frame(), rootId)
                .replace("</body>", "<script src=\"/pathland-dom-renderer.js\" defer></script></body>");
    }

    /** Tear down: close the persistent state, unsubscribe the emitter, drop the connection. */
    public void close() {
        state.close();
        emitter.destroy();
        connection = null;
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

package com.pathland.server;

import com.pathland.view.state.StateStore;
import com.pathland.view.transport.EnvironmentData;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * The application registry: 1:1 sessions keyed by id. Each WebSocket connection owns one
 * {@link PathlandSession}; deltas flow only to that client (never broadcast). Transport-
 * agnostic — the framework starters adapt their connection type to {@link PathlandConnection}.
 *
 * <p>Sessions are created **lazily on the first inbound message**: the platform
 * environment ({@code META::ENVIRONMENT}, spec/OPCODE.md) arrives as the DOM client's
 * first message, and its {@code ROUTE} field seeds the router before mount — so a
 * deep-linked URL renders the right destination and the WebSocket tree stays consistent
 * with the SSR HTML. {@code open} only registers the pending connection; later
 * environment messages **enrich** the session via {@code applyEnvironment}.
 *
 * <p>All session work is serialized on a single actor thread (signals are single-threaded
 * by contract). Per-session SSR runs on the request thread against the thread-safe
 * {@link StateStore} (a throwaway {@link PathlandSession}).
 */
public final class PathlandRegistry {

    private static final int MAX_EVENT_BATCH = 1 << 16;

    private final PathlandApp app;
    private final StateStore store;

    private final ExecutorService actor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "pathland-actor");
        t.setDaemon(true);
        return t;
    });

    private final Map<String, PathlandSession> sessions = new ConcurrentHashMap<>();
    private final Map<String, PathlandConnection> pending = new ConcurrentHashMap<>();

    public PathlandRegistry(PathlandApp app, StateStore store) {
        this.app = app;
        this.store = store;
    }

    /** Render the SSR HTML for a session (request thread), seeding the router from the request path. */
    public String renderHtml(String sessionId, String route) {
        PathlandSession session = new PathlandSession(sessionId, store, app, EnvironmentData.of(route));
        try {
            return session.renderHtml();
        } finally {
            session.close();
        }
    }

    /** Register the connection for a session id; the session is created on its first message. */
    public void open(String sessionId, PathlandConnection connection) {
        actor.execute(() -> {
            PathlandSession previous = sessions.remove(sessionId);
            if (previous != null) {
                previous.close();
            }
            pending.put(sessionId, connection);
        });
    }

    /** Apply the platform environment: creates the session (seeded from its ROUTE field) on first contact, or enriches it after mount. */
    public void environment(String sessionId, EnvironmentData env) {
        actor.execute(() -> session(sessionId, env).applyEnvironment(env));
    }

    /** Route an inbound event batch to the owning session. */
    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) {
            return;
        }
        actor.execute(() -> session(sessionId, EnvironmentData.of("/")).dispatch(message));
    }

    /** Handle a META::RESYNC request: re-send the session's current tree as a snapshot. */
    public void resync(String sessionId) {
        actor.execute(() -> session(sessionId, EnvironmentData.of("/")).resync());
    }

    /** Close and remove a session (and drop any pending connection). */
    public void close(String sessionId) {
        actor.execute(() -> {
            pending.remove(sessionId);
            PathlandSession session = sessions.remove(sessionId);
            if (session != null) {
                session.close();
            }
        });
    }

    /** Shut down the registry: close every session and stop the actor. */
    public void shutdown() {
        for (PathlandSession session : sessions.values()) {
            session.close();
        }
        sessions.clear();
        pending.clear();
        actor.shutdown();
    }

    /** Create the session on first contact, wired to its pending connection. */
    private PathlandSession session(String sessionId, EnvironmentData env) {
        PathlandSession session = sessions.get(sessionId);
        if (session == null) {
            PathlandConnection connection = pending.remove(sessionId);
            session = new PathlandSession(sessionId, store, app, env);
            if (connection != null) {
                session.connect(connection);
            }
            sessions.put(sessionId, session);
        }
        return session;
    }
}

package com.pathland.server;

import com.pathland.state.redis.RedisStateStore;
import com.pathland.view.state.StateStore;

/**
 * Default {@link StateStore} selection: Redis when reachable, otherwise the supplied
 * fallback (typically an in-memory store). The app may override with its own
 * {@code StateStore} bean.
 */
public final class StateStores {

    private StateStores() {}

    /** A Redis store when reachable, else {@code fallback}. */
    public static StateStore redisOrFallback(StateStore fallback) {
        try {
            StateStore redis = new RedisStateStore.Provider().store();
            redis.load("probe", Object.class); // probe connectivity
            log("state store: redis");
            return redis;
        } catch (RuntimeException e) {
            log("state store: in-memory (Redis unavailable: " + e.getMessage() + ")");
            return fallback;
        }
    }

    private static void log(String message) {
        System.out.println("[pathland] " + message);
    }
}

