  --pl-color-primary: #2563eb;
  --pl-color-secondary: #4f46e5;
  --pl-color-surface: #ffffff;
  --pl-color-text-primary: #111827;
  --pl-color-text-secondary: #6b7280;
  --pl-color-text-on-primary: #ffffff;
  --pl-color-border: #e5e7eb;
