 /// Create a ring host over a fresh zero-copy shared ring. Returns an opaque
 /// handle (non-null on success).
 #[no_mangle]
 pub extern "C" fn pathland_core_create() -> CoreHandle {
     let host = Box::new(CoreHost {
         ring: RingTransport::new(),
