         top: f32_prop(node, property_id::PADDING_TOP)
             .map(round_nonneg)
             .unwrap_or(uniform),
         right: f32_prop(node, property_id::PADDING_RIGHT)
             .map(round_nonneg)
             .unwrap_or(uniform),
         bottom: f32_prop(node, property_id::PADDING_BOTTOM)
             .map(round_nonneg)
             .unwrap_or(uniform),
         left: f32_prop(node, property_id::PADDING_LEFT)
             .map(round_nonneg)
             .unwrap_or(uniform),
