             WidgetKind::Picker => {
                 if let Ok(dd) = widget.downcast::<gtk::DropDown>() {
                     let options: Vec<String> = node
                         .children
                         .iter()
                         .filter_map(|c| self.tree.node(*c).and_then(|n| n.text.clone()))
                         .collect();
                     let strings: Vec<&str> = options.iter().map(String::as_str).collect();
