package com.pathland.view;

/**
 * A SwiftUI-{@code @Environment}-style lazy reference: stored as a field, resolved
 * to the current scoped value on each access. Since access happens during render
 * (inside the pushed scope), it mirrors {@code @Environment(\.key)} — unlike a field
 * initializer, which runs at construction before any scope is active.
 *
 * <pre>{@code
 * private final EnvironmentRef<Router> router = EnvironmentRef.of(Navigation.ROUTER);
 *
 * @Override public View body() {
 *     Router router = this.router.get();  // resolves inside the active scope
 *     return ...;
 * }
 * }</pre>
 *
 * <p>Resolves the <em>current</em> scope on every call, so it stays correct even when
 * a structural slot re-applies its environment on re-render.
 */
public final class EnvironmentRef<T> {

    private final EnvironmentKey<T> key;

    private EnvironmentRef(EnvironmentKey<T> key) {
        this.key = key;
    }

    /** A lazy reference to the scoped value bound to {@code key}. */
    public static <T> EnvironmentRef<T> of(EnvironmentKey<T> key) {
        return new EnvironmentRef<>(key);
    }

    /** The current scoped value for the key ({@code null} when absent). */
    public T get() {
        return Environment.value(key);
    }
}

