/** Temporarily set the active scope for a render (save/restore around it). */
    public static void within(EnvironmentValues scope) {
        VALUES.set(scope);
    }

    /** Restore the previous active scope (must pair with a prior {@link #within}). */
    public static void restore(EnvironmentValues previous) {
        VALUES.set(previous);
    }

    // --- SwiftUI-@Environment-style lazy field proxy ---

    /**
     * A lazy reference to the scoped value bound to {@code key} (SwiftUI
     * {@code @Environment}): store it as a field and read it during render, when the
     * scope is active — a field initializer would run at construction, before any
     * scope exists.
     *
     * <pre>{@code
     * private final Environment.Ref<Router> router = Environment.ref(Navigation.ROUTER);
     *
     * @Override public View body() {
     *     Router router = this.router.get();  // resolves inside the active scope
     *     return ...;
     * }
     * }</pre>
     *
     * <p>Resolves the <em>current</em> scope on every access, so it stays correct even
     * when a structural slot re-applies its environment on re-render.
     */
    public static <T> Ref<T> ref(EnvironmentKey<T> key) {
        return new Ref<>(key);
    }

    /** A lazy, key-carrying proxy for a scoped environment value (see {@link #ref}). */
    public static final class Ref<T> {

        private final EnvironmentKey<T> key;

        private Ref(EnvironmentKey<T> key) {
            this.key = key;
        }

        /** The current scoped value for the key ({@code null} when absent). */
        public T get() {
            return value(key);
        }
    }
}

