         Opcode route = frame.opcodes().stream()
                 .filter(o -> o.category() == Categories.STYLE
                         && o.command() == Commands.Style.SET_PROPERTY
                         && (o.b() & 0xFFFF) == Properties.ROUTE)
                 .findFirst().orElseThrow();
