/** Scoped {@code value} for {@code key}, read via the current thread-local scope. */
    public static <T> T value(EnvironmentKey<T> key) {
        return VALUES.get().get(key);
    }

    /**
     * The scoped value for {@code key} as a signal (SwiftUI {@code @Environment},
     * reactive): a value injected as a {@link Signal} is returned as the same
     * instance, so binding it to a node (e.g. {@code Text.of(...)}) re-emits on
     * every change; a plain injected value is wrapped in a constant signal.
     *
     * <pre>{@code
     * Router router = Environment.value(Navigation.ROUTER).get();  // one-off read
     * Text.of(Environment.value(Platform.ACTIVE_PATH));            // reactive binding
     * }</pre>
     *
     * <p>Reads resolve against the <em>current</em> scope, so they must happen during
     * render (inside a pushed scope), not at construction.
     */
    @SuppressWarnings("unchecked")
    public static <T> Signal<T> signal(EnvironmentKey<T> key) {
        T v = VALUES.get().get(key);
        if (v instanceof Signal<?> s) {
            return (Signal<T>) s;
        }
        return () -> v;
    }

    /** Temporarily set the active scope for a render (save/restore around it). */
    public static void within(EnvironmentValues scope) {
        VALUES.set(scope);
    }

    /** Restore the previous active scope (must pair with a prior {@link #within}). */
    public static void restore(EnvironmentValues previous) {
        VALUES.set(previous);
    }
}

