                .filter(o -> o.category() == Categories.STYLE
                        && o.command() == Commands.Style.SET_TEXT
                        && o.a() == nodeId)
                .reduce((a, b) -> b)
                .map(o -> frame.stringAt(o.b()))
                .orElse(null);
    }
