```java
/** A test sink that keeps every completed frame (the built-in sink keeps only the last). */
private static final class AccumulatingSink implements OpcodeSink {
    private final List<Frame> frames = new ArrayList<>();
    private final List<Opcode> ops = new ArrayList<>();
    private final ByteArrayOutputStream strings = new ByteArrayOutputStream();

    @Override public void beginFrame() { ops.clear(); strings.reset(); }
    @Override public void endFrame() {
        frames.add(new Frame(List.copyOf(ops), strings.toByteArray()));
    }
    private void push(int category, int command, int flags, int a, int b, int c) {
        ops.add(new Opcode(category, command, flags, a, b, c));
    }
    private void writeString(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        strings.write(bytes.length & 0xFF);
        strings.write((bytes.length >> 8) & 0xFF);
        strings.write((bytes.length >> 16) & 0xFF);
        strings.write((bytes.length >> 24) & 0xFF);
        strings.writeBytes(bytes);
    }
    @Override public void createNode(int id, int component) { push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0); }
    @Override public void deleteNode(int id) { push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0); }
    @Override public void insertChild(int parent, int child, int index) { push(Categories.TREE, Commands.Tree.INSERT_CHILD, 0, parent, child, index); }
    @Override public void removeChild(int parent, int child) { push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0); }
    @Override public void moveChild(int parent, int child, int newIndex) { push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex); }
    @Override public void setText(int nodeId, String text) { int off = strings.size(); writeString(text); push(Categories.STYLE, Commands.Style.SET_TEXT, 0, nodeId, off, 0); }
    @Override public void setProperty(int nodeId, int property, int valueType, Object value) {
        int b = (valueType << 16) | (property & 0xFFFF);
        if (valueType == ValueTypes.STRING) { int off = strings.size(); writeString((String) value); push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, off); }
        else if (valueType == ValueTypes.DESIGN_TOKEN) { int off = strings.size(); writeString(((Color) value).token()); push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, off); }
        else if (value instanceof Color c) { push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, c.packed()); }
        else { push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, ((Number) value).intValue()); }
    }
    @Override public void setDate(int nodeId, int days, int millisOfDay) { push(Categories.STYLE, Commands.Style.SET_DATE, 0, nodeId, days, millisOfDay); }
    @Override public void setDesignToken(String path, int valueType, Object value) {
        int off = strings.size(); writeString(path);
        int b = valueType;
        if (valueType == ValueTypes.STRING) { int voff = strings.size(); writeString((String) value); push(Categories.STYLE, Commands.Style.SET_DESIGN_TOKEN, 0, off, b, voff); }
        else if (value instanceof Color c) { push(Categories.STYLE, Commands.Style.SET_DESIGN_TOKEN, 0, off, b, c.packed()); }
        else { push(Categories.STYLE, Commands.Style.SET_DESIGN_TOKEN, 0, off, b, ((Number) value).intValue()); }
    }

    List<Frame> frames() { return frames; }
    Frame last() { return frames.get(frames.size() - 1); }
}
